from pathlib import Path
import subprocess,json,statistics,hashlib,os,math
from rusage_counters import collect
root=Path('/tmp/velocity-r16-review/probe-phase-final');root.mkdir(exist_ok=True)
values={}
def quantiles(xs):
 xs=sorted(xs)
 def q(p):
  at=(len(xs)-1)*p;i=int(at);return xs[i]+(xs[min(i+1,len(xs)-1)]-xs[i])*(at-i)
 return {k:q(p)for k,p in [('p50',.5),('p95',.95),('p99',.99)]}
for pair in range(9):
 for label in (['main','candidate']if pair%2==0 else ['candidate','main']):
  binary=Path('/tmp/velocity-r16-review/probe-'+label);out=root/f'{pair+1}-{label}.json';log=out.with_suffix('.log');timing=out.with_suffix('.time')
  if not (out.exists() and timing.exists()):
   print(out.name,flush=True)
   with log.open('w')as f:
    child=subprocess.Popen([str(binary),'--ignored','--exact','view::round16_perf::hot_scenes','--nocapture'],env=dict(os.environ,R16_PERF_OUTPUT=str(out)),stdout=f,stderr=subprocess.STDOUT)
    counters,usage=collect(child)
    if child.returncode:raise RuntimeError(log.read_text())
    timing.write_text(json.dumps({'user_s':usage.ru_utime,'system_s':usage.ru_stime,'maxrss_bytes':usage.ru_maxrss,**counters})+'\n')
  data=json.loads(out.read_text())
  for scenario,row in data.items():
   for unit,stats in [('ms',row['stats_ms']),('instructions',quantiles(row['instructions']))]:
    for p in ['p50','p95','p99']:
     values.setdefault(scenario+'/'+unit+'/'+p,{'main':[],'candidate':[]})[label].append(stats[p])
report={'pairs':9,'binaries':{n:hashlib.sha256(Path('/tmp/velocity-r16-review/probe-'+n).read_bytes()).hexdigest()for n in ['main','candidate']},'metrics':{}}
for name,row in values.items():
 a,b=[statistics.median(row[n])for n in ['main','candidate']]
 report['metrics'][name]={**row,'main_median':a,'candidate_median':b,'delta_pct':100*(b/a-1),'pass_5pct':b<=a*1.05}
report['pass']=all(r['pass_5pct']for r in report['metrics'].values())
(root/'report.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2),flush=True)

