runner_sources.run-benches.py:
from pathlib import Path
import subprocess,json,time,hashlib
r=Path('/tmp/velocity-r16-review2')
commands=[
 ('stress',['python3',str(r/'stress-resources.py')]),
 ('paired-headless',['python3','tools/scroll-gate/paired-headless.py','--base',str(r/'counter-base'),'--candidate',str(r/'counter-candidate'),'--pairs','9','--bench','features','--bench','typing1','--bench','typing1000','--output',str(r/'paired-headless-final')]),
 ('paired-features',['python3',str(r/'paired-phase-probe.py')]),
 ('idle',['python3',str(r/'paired-idle.py')]),
]
results={}
for label,cmd in commands:
 print(label+' running',flush=True)
 with (r/(label+'.log')).open('w')as f:
  at=time.monotonic();status=subprocess.run(cmd,stdout=f,stderr=subprocess.STDOUT).returncode
 results[label]={'command':cmd,'exit':status,'elapsed_s':time.monotonic()-at}
 (r/'bench-runs.json').write_text(json.dumps(results,indent=2)+'\n')
 print(label+' exit '+str(status),flush=True)
 if status:raise SystemExit(status)
 if label=='paired-features':
  assert json.loads((r/'probe-phase-final/report.json').read_text())['pass'], 'feature phase budget exceeded'

